sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var fields = MgrHubUtils.FIELDS;
    var utils = new MgrHubUtils();



    // 2. Only re-validate when a date changed.
    if (!current.isNewRecord() && !current[fields.DUE_DATE].changes() && !current[fields.REQUEST_DATE].changes())
        return;

    var check = utils.validateDates(current.getValue(fields.REQUEST_DATE), current.getValue(fields.DUE_DATE));
    if (!check.valid) {
        gs.addErrorMessage(gs.getMessage('Due Date ({0}) cannot be earlier than the Request Date ({1}).',
            [current[fields.DUE_DATE].getDisplayValue(),
             current[fields.REQUEST_DATE].getDisplayValue() || utils.today()]));
        current.setAbortAction(true);
        return;
    }

    // 3. Persist Days to Due
    var days = utils.calcDaysToDue(current.getValue(fields.DUE_DATE));
    current.setValue('days_to_due', days === null ? '' : days);
})(current, previous);
